# (cat, qAr, qEn, aAr, aEn)
FAQ_CATEGORIES_EXTRA = {"purity": ("الطهارة", "Purification"), "quran": ("القرآن", "The Quran"), "transactions": ("المعاملات", "Transactions"), "family": ("الأسرة", "Family"), "women": ("أحكام النساء", "Women’s rulings"), "manners": ("الآداب", "Manners")}
FAQ_EXTRA = [
    ("purity", "ما فروض الوضوء؟", "What are the obligatory parts of wudu?", "غسل الوجه، وغسل اليدين إلى المرفقين، ومسح الرأس، وغسل الرجلين إلى الكعبين، كما في سورة المائدة، الآية ٦.", "Washing the face, washing the arms to the elbows, wiping the head and washing the feet to the ankles, as in Surat al-Ma’idah, verse 6."),
    ("purity", "ما الذي ينقض الوضوء؟", "What invalidates wudu?", "خروج شيء من السبيلين (بول أو غائط أو ريح)، وزوال العقل بنوم عميق أو إغماء أو جنون. وفي أمور أخرى خلاف بين المذاهب.", "Anything leaving the private parts (urine, stool, wind), and loss of awareness through deep sleep, fainting or insanity. Other matters are differed upon by the schools."),
    ("purity", "متى يجب الغسل؟", "When is ghusl required?", "بعد الجنابة، وبعد انقطاع دم الحيض والنفاس.", "After janabah, and after menstrual and post-natal bleeding ends."),
    ("purity", "ما حكم التيمم؟", "What is the ruling on tayammum?", "هو بدل عن الوضوء أو الغسل عند عدم وجود الماء أو العجز عن استعماله، بضرب التراب ومسح الوجه واليدين.", "A substitute for wudu or ghusl when water is unavailable or cannot be used: strike clean earth and wipe the face and hands."),
    ("prayer", "ما أوقات الصلوات الخمس؟", "What are the times of the five prayers?", "الفجر من الفجر الصادق إلى الشروق، والظهر من زوال الشمس، والعصر إذا صار ظل الشيء مثله (أو مثليه عند الحنفية)، والمغرب من الغروب، والعشاء من غياب الشفق.", "Fajr from true dawn to sunrise; Dhuhr from the sun’s decline; ‘Asr when an object’s shadow equals its length (twice, for the Hanafis); Maghrib from sunset; ‘Isha from the disappearance of twilight."),
    ("prayer", "ما عدد ركعات كل صلاة؟", "How many rak‘ahs is each prayer?", "الفجر ٢، والظهر ٤، والعصر ٤، والمغرب ٣، والعشاء ٤، والجمعة ركعتان.", "Fajr 2, Dhuhr 4, ‘Asr 4, Maghrib 3, ‘Isha 4, and Jumu‘ah 2."),
    ("prayer", "ما حكم قصر الصلاة في السفر؟", "Can prayers be shortened while travelling?", "يُشرع قصر الصلاة الرباعية إلى ركعتين للمسافر، وللمسافة المعتبرة تقديرات تختلف بين المذاهب (نحو ٨٠ كم عند الجمهور).", "A traveller shortens four-rak‘ah prayers to two. The qualifying distance is estimated differently by the schools (about 80 km for most)."),
    ("prayer", "هل يجوز الجمع بين الصلاتين؟", "May two prayers be combined?", "يجوز عند الجمهور الجمع بين الظهر والعصر وبين المغرب والعشاء لعذر كالسفر والمطر الشديد، وتختلف المذاهب في التفاصيل؛ ويمنعه الحنفية إلا في عرفة ومزدلفة.", "Most scholars allow combining Dhuhr with ‘Asr and Maghrib with ‘Isha for a valid excuse such as travel or heavy rain, with differences in the details; the Hanafis allow it only at ‘Arafah and Muzdalifah."),
    ("prayer", "ما صلاة الوتر؟", "What is the Witr prayer?", "صلاة تُختم بها صلاة الليل، ركعة فأكثر. هي سنة مؤكدة عند الجمهور وواجبة عند الحنفية.", "The prayer that concludes the night prayer, one rak‘ah or more. It is a confirmed Sunnah for most scholars and wajib for the Hanafis."),
    ("prayer", "ما صلاة التراويح؟", "What is Taraweeh?", "قيام الليل في رمضان جماعة بعد العشاء، وعدد ركعاتها فيه سعة؛ فقد عُمل بإحدى عشرة وبعشرين ركعة.", "The night prayer of Ramadan prayed in congregation after ‘Isha; its number of rak‘ahs is flexible, with eleven and twenty both practised."),
    ("prayer", "ما سجود السهو؟", "What is the prostration of forgetfulness?", "سجدتان يؤديهما المصلي لجبر نقص أو زيادة أو شك وقع في الصلاة.", "Two prostrations made to make up for an omission, addition or doubt that occurred in the prayer."),
    ("fasting", "من يجوز له الفطر في رمضان؟", "Who may break the fast in Ramadan?", "المريض والمسافر يفطران ويقضيان بعد رمضان، والحائض والنفساء تفطران وتقضيان، والكبير العاجز يطعم عن كل يوم مسكينًا.", "The sick and the traveller break the fast and make it up later; a menstruating or post-natal woman does the same; a frail elder feeds a poor person for each day."),
    ("fasting", "ما الفدية؟", "What is the fidyah?", "إطعام مسكين عن كل يوم لمن لا يستطيع الصيام ولا القضاء لكبر سن أو مرض لا يُرجى برؤه.", "Feeding a poor person for each day, for someone who cannot fast or make it up because of old age or an illness with no hope of recovery."),
    ("fasting", "هل يُستحب صيام التطوع؟", "Is voluntary fasting encouraged?", "نعم، منه الاثنين والخميس، وثلاثة أيام من كل شهر، وست من شوال، ويوم عرفة، وعاشوراء.", "Yes — Mondays and Thursdays, three days of each month, six days of Shawwal, the day of ‘Arafah and ‘Ashura."),
    ("fasting", "ما الاعتكاف؟", "What is i‘tikaf?", "لزوم المسجد للعبادة مدة معينة، وأفضله في العشر الأواخر من رمضان.", "Staying in the mosque for worship for a set period, best in the last ten nights of Ramadan."),
    ("zakat", "على أي الأموال تجب الزكاة؟", "On which wealth is zakat due?", "على الذهب والفضة والنقود وعروض التجارة، وبهيمة الأنعام والزروع والثمار بشروطها.", "On gold, silver, cash and trade goods, and on livestock, crops and fruit under their conditions."),
    ("zakat", "من هم مستحقو الزكاة؟", "Who may receive zakat?", "ثمانية أصناف ذكرتهم الآية ٦٠ من سورة التوبة: الفقراء والمساكين والعاملون عليها والمؤلفة قلوبهم وفي الرقاب والغارمون وفي سبيل الله وابن السبيل.", "Eight categories named in Surat at-Tawbah, verse 60: the poor, the needy, those who administer it, those whose hearts are to be reconciled, freeing captives, those in debt, in Allah’s cause and the wayfarer."),
    ("zakat", "ما مقدار زكاة الفطر؟", "How much is Zakat al-Fitr?", "صاع من طعام أهل البلد عن كل فرد، ويقارب ثلاثة كيلوغرامات، وتجوز قيمته عند بعض المذاهب.", "One sa‘ of the local staple food per person, about three kilograms; some schools allow giving its value."),
    ("hajj", "ما أركان الحج؟", "What are the pillars of Hajj?", "الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي عند الجمهور.", "Ihram, standing at ‘Arafah, Tawaf al-Ifadah and, for most scholars, sa‘i."),
    ("hajj", "ما أنواع الحج؟", "What are the types of Hajj?", "التمتع: عمرة ثم حج في العام نفسه بإحرامين، والقِران: العمرة والحج بإحرام واحد، والإفراد: الحج وحده.", "Tamattu‘: ‘Umrah then Hajj in the same season with two ihrams; Qiran: ‘Umrah and Hajj together with one ihram; Ifrad: Hajj alone."),
    ("hajj", "ما حكم العمرة؟", "What is the ruling on ‘Umrah?", "واجبة عند الشافعية والحنابلة، وسنة مؤكدة عند الحنفية والمالكية، وتجوز في أي وقت من السنة.", "Obligatory for the Shafi‘is and Hanbalis, a confirmed Sunnah for the Hanafis and Malikis; it may be done at any time of year."),
    ("hajj", "ما محظورات الإحرام؟", "What is forbidden in ihram?", "إزالة الشعر والأظفار، والطيب، وتغطية رأس الرجل، ولبس المخيط للرجل، وصيد البر، وعقد النكاح، والجماع ومقدماته.", "Removing hair or nails, perfume, covering a man’s head, wearing stitched clothing for men, hunting, marriage contracts, and marital relations."),
    ("quran", "كم عدد سور القرآن وآياته؟", "How many surahs and ayahs are in the Quran?", "١١٤ سورة، وفي رواية حفص عن عاصم ٦٢٣٦ آية، وهو العدد المعتمد في هذا التطبيق.", "114 surahs; in the riwayah of Hafs ‘an ‘Asim, 6,236 ayahs — the count used in this app."),
    ("quran", "ما أطول سورة وأقصرها؟", "What are the longest and shortest surahs?", "أطولها البقرة (٢٨٦ آية)، وأقصرها في عدد الكلمات الكوثر (٣ آيات)، وتشاركها في عدد الآيات العصر والنصر.", "The longest is Al-Baqarah (286 ayahs); the shortest by word count is Al-Kawthar (3 ayahs), a length shared by Al-‘Asr and An-Nasr."),
    ("quran", "ما الفرق بين المكي والمدني؟", "What is the difference between Makki and Madani surahs?", "المكي ما نزل قبل الهجرة غالبًا، وفيه التوحيد والبعث، والمدني ما نزل بعدها، وفيه الأحكام والتشريع.", "Makki surahs were mostly revealed before the Hijrah and stress tawhid and the Hereafter; Madani surahs came after and stress rulings and legislation."),
    ("quran", "كم جزءًا في القرآن؟", "How many juz’ are there?", "ثلاثون جزءًا، يُقسَّم المصحف بها لتيسير الختمة في شهر.", "Thirty, dividing the mushaf so that it can be completed in a month."),
    ("quran", "متى نزل القرآن؟", "When was the Quran revealed?", "بدأ نزوله في ليلة القدر من رمضان، ونزل منجَّمًا على النبي ﷺ في نحو ثلاث وعشرين سنة.", "It began descending on the Night of Qadr in Ramadan and was revealed gradually to the Prophet ﷺ over about twenty-three years."),
    ("faith", "من أولو العزم من الرسل؟", "Who are the messengers of firm resolve (Ulul-‘Azm)?", "نوح وإبراهيم وموسى وعيسى ومحمد عليهم الصلاة والسلام.", "Nuh, Ibrahim, Musa, ‘Isa and Muhammad, peace be upon them."),
    ("faith", "كم عدد الأنبياء المذكورين في القرآن؟", "How many prophets are named in the Quran?", "خمسة وعشرون نبيًّا ورسولًا مذكورون بأسمائهم، وأولهم آدم وآخرهم محمد ﷺ.", "Twenty-five prophets and messengers are named, the first Adam and the last Muhammad ﷺ."),
    ("faith", "ما هو التوحيد؟", "What is tawhid?", "إفراد الله بالعبادة والربوبية والأسماء والصفات، وهو أصل الدين.", "Singling out Allah in worship, lordship, and His names and attributes; it is the foundation of the religion."),
    ("faith", "ما الفرق بين الإسلام والإيمان؟", "What is the difference between Islam and Iman?", "الإسلام هو الأعمال الظاهرة الخمسة، والإيمان هو الأصول الباطنة الستة، كما في حديث جبريل المشهور.", "Islam is the five outward pillars and Iman the six inner articles of belief, as in the well-known hadith of Jibril."),
]

# Practical questions (transactions, family, women, manners) added with the
# categorised Q&A; mainstream positions, with differences noted.
FAQ_EXTRA += [
    ("purity", "ما حكم المسح على الخفين؟", "May one wipe over leather socks (khuffs)?", "جائز إذا لُبسا على طهارة، ومدته يوم وليلة للمقيم وثلاثة أيام بلياليها للمسافر، ويُمسح أعلاهما.", "Yes, if they were put on in a state of purity. The period is a day and a night for a resident and three days and nights for a traveller, wiping over the top."),
    ("prayer", "ما حكم قضاء الصلوات الفائتة؟", "How are missed prayers made up?", "من فاتته صلاة بنوم أو نسيان صلّاها متى ذكرها، لحديث «من نسي صلاة أو نام عنها فكفارتها أن يصليها إذا ذكرها» (مسلم ٦٨٤). ومن تركها عمدًا فجمهور العلماء على وجوب قضائها مع التوبة، وذهب بعضهم إلى أنه يتوب ويكثر من النوافل.", "Whoever misses a prayer through sleep or forgetfulness prays it when he remembers, as in the hadith “Whoever forgets a prayer or sleeps through it, its expiation is to pray it when he remembers it” (Muslim 684). For a prayer left deliberately, most scholars require making it up along with repentance; some hold that one repents and increases voluntary prayers."),
    ("prayer", "ما أوقات النهي عن الصلاة؟", "When is voluntary prayer not allowed?", "بعد صلاة الفجر حتى ترتفع الشمس قدر رمح، وعند استوائها في وسط السماء حتى تزول، وبعد صلاة العصر حتى تغرب. واستثنى جمع من العلماء ما له سبب كتحية المسجد وقضاء الفائتة.", "After Fajr until the sun has risen a spear’s length, when it is at its zenith until it passes, and after ‘Asr until sunset. Many scholars exempt prayers with a cause, such as greeting the mosque or making up a missed prayer."),
    ("prayer", "كيف أصلي في الطائرة؟", "How do I pray on a plane?", "إن خشيت خروج وقت الفريضة قبل الهبوط صلّيتها في الطائرة، مستقبلًا القبلة قدر استطاعتك، قائمًا إن أمكن وإلا جالسًا. ويجوز جمعها مع ما بعدها أو قبلها لمن يجمع في السفر.", "If the time of an obligatory prayer will end before landing, pray it on board, facing the Qibla as best you can, standing if possible and otherwise seated. Travellers may also combine it with the prayer before or after."),
    ("fasting", "هل يفطر من أكل أو شرب ناسيًا؟", "Does eating by mistake break the fast?", "لا، يُتمّ صومه، لحديث «من نسي وهو صائم فأكل أو شرب فليتمّ صومه، فإنما أطعمه الله وسقاه» (البخاري ١٩٣٣، ومسلم ١١٥٥).", "No, he completes his fast, as in the hadith “Whoever forgets while fasting and eats or drinks, let him complete his fast, for it was Allah who fed him and gave him drink” (al-Bukhari 1933, Muslim 1155)."),
    ("fasting", "ما حكم من أفطر في رمضان بغير عذر؟", "What if someone breaks a Ramadan fast without excuse?", "يأثم وعليه التوبة والقضاء. فإن كان الفطر بالجماع في نهار رمضان فعليه مع القضاء الكفارة: عتق رقبة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا.", "It is a sin requiring repentance and making the day up. If it was by intercourse during the day, an expiation is due as well: freeing a slave, or if not possible two consecutive months of fasting, or if not possible feeding sixty poor people."),
    ("transactions", "ما الربا؟", "What is riba (usury)?", "الزيادة المشترطة في القرض، والزيادة أو التأجيل في مبادلة الأموال الربوية كالذهب والفضة والنقود. وهو من كبائر الذنوب، وقد حرّمه الله في سورة البقرة (الآيات ٢٧٥–٢٧٩).", "Any increase stipulated on a loan, and increase or delay when exchanging usurious goods such as gold, silver and money. It is a major sin, prohibited in Surat al-Baqarah (verses 275–279)."),
    ("transactions", "ما حكم البيع بالتقسيط؟", "Is buying in instalments allowed?", "جائز عند جمهور العلماء ولو كان الثمن المؤجل أكثر من الحالّ، بشرط أن يُحدَّد الثمن عند العقد، وألا تُشترط زيادة أو غرامة عند التأخر في السداد.", "Most scholars permit it even when the deferred price exceeds the cash price, provided the price is fixed at the contract and no increase or penalty is stipulated for late payment."),
    ("transactions", "ما حكم الغش في البيع؟", "What is the ruling on cheating in trade?", "محرّم، قال ﷺ: «من غشّنا فليس منا» (مسلم ١٠١). ومنه كتمان العيب، والتطفيف في الكيل والوزن، والكذب في وصف السلعة.", "Forbidden; the Prophet ﷺ said: “Whoever cheats us is not one of us” (Muslim 101). It includes hiding defects, short measure and weight, and lying about goods."),
    ("transactions", "ما أحكام القرض؟", "What are the rules of lending?", "الإقراض مستحب لما فيه من التيسير، ويجب على المقترض الوفاء، ولا يجوز اشتراط زيادة على أصل القرض لأنها ربا. وأمر الله بكتابة الدَّين في آية الدَّين (البقرة ٢٨٢).", "Lending is recommended as an ease to others; the borrower must repay, and stipulating any increase over the principal is riba. Allah commanded writing debts down in the verse of debt (al-Baqarah 282)."),
    ("transactions", "ماذا أفعل إذا وجدت مالًا ضائعًا (لقطة)؟", "What should I do with lost property I find?", "تُعرِّفه سنة في مظانّ وجود صاحبه، فإن جاء دفعته إليه، وإلا انتفعت به مع ضمانه إن ظهر صاحبه بعد ذلك (البخاري ٢٣٧٢، ومسلم ١٧٢٢). والشيء اليسير الذي لا تلتفت إليه النفوس لا يلزم تعريفه.", "Announce it for a year where its owner may be found; if he comes, return it, otherwise you may use it while owing it to him if he appears later (al-Bukhari 2372, Muslim 1722). Trivial items people do not look for need no announcement."),
    ("transactions", "هل يجوز أخذ أجرة على الوساطة (السمسرة)؟", "Is a brokerage fee allowed?", "نعم، يجوز أخذ أجرة معلومة على الدلالة والسمسرة إذا خلت من الغش والكذب، وعلم بها الطرفان.", "Yes, a known fee for brokering is allowed when free of deceit and lies and known to both parties."),
    ("family", "ما أركان عقد النكاح؟", "What makes a marriage contract valid?", "الإيجاب والقبول بين الزوجين، مع حضور شاهدين، ويشترط الجمهور الوليّ خلافًا للحنفية، والمهر حق للزوجة.", "Offer and acceptance between the spouses with two witnesses; most scholars also require the bride’s guardian (the Hanafis do not), and the dower (mahr) is the wife’s right."),
    ("family", "ما حقوق الزوجة على زوجها؟", "What are a wife’s rights?", "المهر، والنفقة بالمعروف من طعام وكسوة وسكن، والمعاشرة بالمعروف، والعدل بين الزوجات لمن عدّد.", "Her dower, maintenance by what is customary (food, clothing, housing), kind companionship, and justice between wives for a man with more than one."),
    ("family", "ما حقوق الزوج على زوجته؟", "What are a husband’s rights?", "طاعته في المعروف، وحفظه في نفسها وماله وبيته، وألا تأذن في بيته لمن يكره.", "Obedience in what is right, guarding herself, his property and his home, and not admitting into his home anyone he dislikes."),
    ("family", "ما حق الجار؟", "What is owed to a neighbour?", "الإحسان إليه وكفّ الأذى عنه، قال ﷺ: «ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورّثه» (البخاري ٦٠١٤، ومسلم ٢٦٢٥).", "Kindness and not harming him; the Prophet ﷺ said: “Jibril kept advising me about the neighbour until I thought he would make him an heir” (al-Bukhari 6014, Muslim 2625)."),
    ("family", "ما صلة الرحم؟", "What is keeping family ties?", "الإحسان إلى الأقارب بالزيارة والسؤال والهدية والعون، وقطعها من الكبائر، قال ﷺ: «لا يدخل الجنة قاطع» (البخاري ٥٩٨٤، ومسلم ٢٥٥٦).", "Doing good to relatives by visiting, asking after them, gifts and help. Cutting them off is a major sin; the Prophet ﷺ said: “One who severs ties will not enter Paradise” (al-Bukhari 5984, Muslim 2556)."),
    ("family", "كيف تُقسم التركة باختصار؟", "How is an estate divided, in brief?", "تُخرج من التركة أولًا تكاليف التجهيز، ثم الديون، ثم الوصية في حدود الثلث لغير وارث، ثم يُقسم الباقي على الورثة بالفروض المبيّنة في سورة النساء (الآيات ١١ و١٢ و١٧٦). ويُستحسن الرجوع إلى مختص لحساب الأنصبة.", "First the funeral costs, then debts, then any bequest up to a third to non-heirs; the rest goes to the heirs by the shares set out in Surat an-Nisa’ (verses 11, 12 and 176). It is best to have a specialist calculate the shares."),
    ("women", "ما الذي يُمنع على الحائض؟", "What may a menstruating woman not do?", "الصلاة والصيام والطواف والجماع، وتقضي الصيام دون الصلاة، لقول عائشة: «كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة» (مسلم ٣٣٥). وفي قراءتها القرآن ومسّها المصحف خلاف بين العلماء.", "Prayer, fasting, tawaf and intercourse. She makes up the fasts but not the prayers, as ‘A’ishah said: “We were ordered to make up fasts and not ordered to make up prayers” (Muslim 335). Scholars differ on her reciting the Quran and touching the mushaf."),
    ("women", "ما الاستحاضة؟", "What is istihadah (irregular bleeding)?", "دم يخرج في غير وقت الحيض والنفاس لعلّة، وحكم صاحبتها حكم الطاهرات: تصلي وتصوم، وتتوضأ لكل صلاة عند الجمهور.", "Bleeding outside the times of menstruation and post-natal bleeding, due to a condition. The woman is treated as pure: she prays and fasts, and most scholars have her make wudu for each prayer."),
    ("women", "هل تفطر الحامل والمرضع في رمضان؟", "May a pregnant or nursing woman break the fast?", "إن خافتا على نفسيهما أو على الولد جاز لهما الفطر، وعليهما القضاء، وأوجب بعض العلماء مع القضاء إطعام مسكين عن كل يوم إذا كان الخوف على الولد وحده.", "If they fear for themselves or for the child they may break the fast and make it up later; some scholars add feeding a poor person for each day when the fear is for the child alone."),
    ("women", "ما شروط الحجاب الشرعي؟", "What are the conditions of hijab?", "أن يستر البدن عدا ما استُثني، وألا يكون شفافًا ولا ضيّقًا يصف، ولا زينةً في نفسه. وفي ستر الوجه والكفين خلاف معروف بين العلماء.", "That it covers the body except what is exempted, is neither see-through nor tight enough to show the shape, and is not an adornment in itself. Scholars differ well-knownly on covering the face and hands."),
    ("women", "هل تحج المرأة بلا محرم؟", "May a woman perform Hajj without a mahram?", "اشترط جمهور العلماء المحرم لسفر المرأة، وأجاز بعضهم حج الفريضة مع رفقة مأمونة.", "Most scholars require a mahram for a woman’s travel; some allow the obligatory Hajj in trustworthy company."),
    ("manners", "ما آداب الطعام؟", "What are the manners of eating?", "التسمية في أوله، والأكل باليمين ومما يليك، وحمد الله في آخره، لحديث «يا غلام، سمِّ الله، وكُل بيمينك، وكُل مما يليك» (البخاري ٥٣٧٦، ومسلم ٢٠٢٢).", "Saying Bismillah at the start, eating with the right hand from what is in front of you, and praising Allah at the end, as in the hadith “Young man, mention Allah’s name, eat with your right hand and eat from what is in front of you” (al-Bukhari 5376, Muslim 2022)."),
    ("manners", "ما آداب السلام؟", "What are the manners of greeting?", "يسلّم الصغير على الكبير، والمارّ على القاعد، والقليل على الكثير (البخاري ٦٢٣١)، وردّ السلام واجب.", "The younger greets the elder, the passer-by the one seated, and the few the many (al-Bukhari 6231); returning the greeting is obligatory."),
    ("manners", "ماذا يقال عند العطاس؟", "What is said when someone sneezes?", "يقول العاطس: الحمد لله، ويقول له من سمعه: يرحمك الله، فيردّ: يهديكم الله ويصلح بالكم (البخاري ٦٢٢٤).", "The one who sneezes says al-hamdu lillah; whoever hears says yarhamuk Allah, and he replies yahdikumullah wa yuslih balakum (al-Bukhari 6224)."),
    ("manners", "ما آداب الاستئذان؟", "How should one ask permission to enter?", "يستأذن ثلاثًا مع السلام، فإن أُذن له وإلا رجع (البخاري ٦٢٤٥، ومسلم ٢١٥٣)، ولا يقف مستقبل الباب.", "Ask permission up to three times with a greeting; if permitted enter, otherwise leave (al-Bukhari 6245, Muslim 2153), and do not stand facing the doorway."),
    ("manners", "ما الغيبة والنميمة؟", "What are backbiting and tale-bearing?", "الغيبة: «ذكرك أخاك بما يكره» (مسلم ٢٥٨٩)، والنميمة: نقل الكلام بين الناس للإفساد، وكلتاهما من كبائر الذنوب.", "Backbiting is “mentioning your brother with what he dislikes” (Muslim 2589); tale-bearing is carrying words between people to sow discord. Both are major sins."),
]

# ------------------------------------------------------------------ Hajj and Umrah: general guide
HAJJ_GUIDE = [
    ("guide", "أنواع النسك", "The three forms", "التمتع: عمرة ثم حج في العام نفسه. القِران: العمرة والحج بإحرام واحد. الإفراد: الحج وحده. وأفضلها عند كثير من العلماء التمتع.", "Tamattu‘: ‘Umrah then Hajj in the same season. Qiran: both with one ihram. Ifrad: Hajj alone. Many scholars hold Tamattu‘ the best."),
    ("guide", "المواقيت", "The miqats", "ذو الحليفة لأهل المدينة، والجحفة لأهل الشام ومصر والمغرب، وقرن المنازل لأهل نجد، ويلملم لأهل اليمن، وذات عرق لأهل العراق.", "Dhul-Hulayfah for the people of Madinah; Al-Juhfah for Syria, Egypt and the Maghrib; Qarn al-Manazil for Najd; Yalamlam for Yemen; Dhat ‘Irq for Iraq."),
    ("guide", "لباس الإحرام", "Ihram dress", "يلبس الرجل إزارًا ورداءً أبيضين غير مخيطين، وتلبس المرأة ما شاءت من ثياب ساترة دون نقاب ولا قفازين.", "A man wears two white unstitched sheets; a woman wears ordinary modest clothing without a face-veil or gloves."),
    ("guide", "محظورات الإحرام", "Prohibitions of ihram", "إزالة الشعر والأظفار، والطيب، وتغطية رأس الرجل، ولبس المخيط للرجل، وصيد البر، وعقد النكاح، والجماع ومقدماته.", "Removing hair or nails, perfume, covering a man’s head, stitched clothing for men, hunting, marriage contracts, and marital relations."),
    ("guide", "أركان الحج", "Pillars of Hajj", "الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي عند الجمهور.", "Ihram, standing at ‘Arafah, Tawaf al-Ifadah and, for most, sa‘i."),
    ("guide", "الأدعية والأذكار", "Supplications", "في «حصن المسلم» أبواب خاصة بالحج: التلبية، والدعاء بين الركن اليماني والحجر الأسود، وعلى الصفا والمروة، ويوم عرفة، والتكبير عند رمي الجمار.", "Hisn al-Muslim has dedicated chapters for Hajj: the talbiyah, the supplication between the Yemeni corner and the Black Stone, at Safa and Marwah, on ‘Arafah, and the takbir when stoning."),
]

